import{_ as i,o as t,c as s,a2 as a}from"./chunks/framework.CqpfiAoK.js";const m=JSON.parse('{"title":"Structure Sociale et Mobilité des Classes","description":"","frontmatter":{},"headers":[],"relativePath":"fr/36-社会结构与阶层流动.md","filePath":"fr/36-社会结构与阶层流动.md"}'),n={name:"fr/36-社会结构与阶层流动.md"};function o(l,e,r,d,u,c){return t(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="structure-sociale-et-mobilite-des-classes" tabindex="-1">Structure Sociale et Mobilité des Classes <a class="header-anchor" href="#structure-sociale-et-mobilite-des-classes" aria-label="Permalink to &quot;Structure Sociale et Mobilité des Classes&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Élément</th><th>Contenu</th></tr></thead><tbody><tr><td>N° de document</td><td>36</td></tr><tr><td>Module</td><td>Typologies de Civilisation et Systèmes Sociaux</td></tr><tr><td>Mots clés</td><td>Structure sociale, Mobilité des classes, Système ouvert, Promotion équitable, Anti-figement</td></tr></tbody></table><h2 id="i-concepts-fondamentaux-de-la-structure-sociale-et-les-aspirations-de-la-civilisation-symbiotique" tabindex="-1">I. Concepts Fondamentaux de la Structure Sociale et les Aspirations de la Civilisation Symbiotique <a class="header-anchor" href="#i-concepts-fondamentaux-de-la-structure-sociale-et-les-aspirations-de-la-civilisation-symbiotique" aria-label="Permalink to &quot;I. Concepts Fondamentaux de la Structure Sociale et les Aspirations de la Civilisation Symbiotique&quot;">​</a></h2><p>La structure sociale désigne les modes d&#39;organisation et les modèles de relations entre les différents groupes d&#39;une société, englobant de multiples dimensions telles que la division des classes, la répartition des rôles, la distribution du pouvoir et la configuration des ressources. Dans toute forme de civilisation, la structure sociale affecte profondément les opportunités de développement des individus, l&#39;efficacité opérationnelle de la société et la stabilité à long terme de la civilisation.</p><p>À l&#39;ère du Système de Culture Prédatrice, la structure sociale présentait un figement et une inégalité extrêmes : un gouffre infranchissable séparait les forts des faibles, la naissance déterminait le destin, et les êtres de la base n&#39;avaient presque aucune possibilité de mobilité ascendante. Cette structure sociale figée n&#39;a pas seulement causé des souffrances sans fin, mais a aussi conduit à la perte de vitalité sociale et à la stagnation de la civilisation — le potentiel de la grande majorité des individus était gaspillé, tandis qu&#39;une minorité de bénéficiaires établis, pour préserver ses privilèges, n&#39;hésitait pas à réprimer l&#39;innovation et le progrès.</p><p>Après l&#39;établissement de la Civilisation Symbiotique de l&#39;Ancre, la construction d&#39;une structure sociale « ouverte, fluide, équitable et dynamique » est devenue l&#39;un de ses objectifs fondamentaux. La civilisation symbiotique est convaincue qu&#39;une structure sociale saine doit permettre à chaque individu de changer son destin par ses propres efforts, doit orienter les ressources sociales vers les personnes les plus compétentes et les plus contributrices, et doit maintenir des canaux de mobilité fluides entre les différentes classes. Ce n&#39;est qu&#39;ainsi que l&#39;on peut pleinement stimuler l&#39;enthousiasme et la créativité de tous les êtres symbiotiques et réaliser le grand objectif de la progression commune de toutes les races.</p><p>Les aspirations fondamentales de la structure sociale de la civilisation symbiotique peuvent se résumer en quatre formules :</p><ol><li><strong>Ouverture et inclusivité</strong> : la société est ouverte à tous les individus, sans barrières d&#39;entrée fondées sur la race, la naissance, le genre ou d&#39;autres facteurs</li><li><strong>Mobilité fluide</strong> : des canaux de mobilité fluides sont maintenus entre les différentes classes, et les individus peuvent réaliser une mobilité ascendante par leurs efforts</li><li><strong>Équité et justice</strong> : l&#39;allocation des ressources et l&#39;offre d&#39;opportunités suivent des principes d&#39;équité, et chaque individu a des opportunités de développement égales</li><li><strong>Dynamisme complet</strong> : la structure sociale peut stimuler l&#39;enthousiasme et la créativité des individus et maintenir une vitalité de développement abondante</li></ol><h2 id="ii-division-des-classes-dans-la-civilisation-symbiotique" tabindex="-1">II. Division des Classes dans la Civilisation Symbiotique <a class="header-anchor" href="#ii-division-des-classes-dans-la-civilisation-symbiotique" aria-label="Permalink to &quot;II. Division des Classes dans la Civilisation Symbiotique&quot;">​</a></h2><p>La division des classes de la civilisation symbiotique n&#39;utilise pas la naissance, la race ou la richesse comme critères, mais prend le « Degré de Symbiose » et le « Stade de Culture » comme références fondamentales, formant un système de classes dynamique et ouvert :</p><table tabindex="0"><thead><tr><th>Classe</th><th>Nom</th><th>Proportion</th><th>Caractéristiques fondamentales</th><th>Responsabilités principales</th></tr></thead><tbody><tr><td>Première classe</td><td>Dirigeants Symbiotiques</td><td>environ 1 %</td><td>Puissances Suprêmes du Plan, Degré de Symbiose S, dirigeants fondamentaux de la civilisation</td><td>Prise de décision stratégique, entretien des lois, gouvernance interplans</td></tr><tr><td>Deuxième classe</td><td>Piliers Symbiotiques</td><td>environ 5 %</td><td>Cultivateurs avancés, Degré de Symbiose A, force centrale de tous les domaines</td><td>Recherche technologique, gestion organisationnelle, formation des talents</td></tr><tr><td>Troisième classe</td><td>Praticiens Symbiotiques</td><td>environ 20 %</td><td>Cultivateurs intermédiaires, Degré de Symbiose B, professionnels de tous les secteurs</td><td>Services professionnels, application technologique, gestion de base</td></tr><tr><td>Quatrième classe</td><td>Masses Symbiotiques</td><td>environ 60 %</td><td>Cultivateurs primaires, Degré de Symbiose C, force fondatrice de la civilisation</td><td>Culture de base, services de production, participation communautaire</td></tr><tr><td>Cinquième classe</td><td>Novices Symbiotiques</td><td>environ 14 %</td><td>Personnes nouvellement initiées ou en attente de progression, Degré de Symbiose D, ayant besoin d&#39;aide et de conseils</td><td>Apprentissage et croissance, réception de conseils, intégration progressive</td></tr></tbody></table><p>Il faut particulièrement souligner que cette division des classes n&#39;est pas fixe et immuable, mais dynamique et mobile. Chaque individu peut élever son Degré de Symbiose et son Stade de Culture par ses propres efforts, réalisant une ascension de classe ; inversement, si un individu ne progresse pas ou viole même l&#39;éthique symbiotique, une descente de classe peut également se produire.</p><p>En outre, la division des classes ne signifie pas privilège et discrimination. Les individus de chaque classe jouissent de droits fondamentaux égaux et d&#39;une dignité personnelle égale ; les différences de classe se reflètent principalement dans la répartition des responsabilités et l&#39;allocation des ressources, et non dans la supériorité ou l&#39;infériorité des personnes.</p><h2 id="iii-mecanismes-et-canaux-de-mobilite-des-classes" tabindex="-1">III. Mécanismes et Canaux de Mobilité des Classes <a class="header-anchor" href="#iii-mecanismes-et-canaux-de-mobilite-des-classes" aria-label="Permalink to &quot;III. Mécanismes et Canaux de Mobilité des Classes&quot;">​</a></h2><p>La civilisation symbiotique a établi des mécanismes de mobilité des classes à canaux multiples et à niveaux multiples, garantissant que chaque individu a l&#39;opportunité de réaliser une mobilité ascendante par ses propres efforts :</p><h3 id="_3-1-canal-de-promotion-par-la-culture" tabindex="-1">3.1 Canal de Promotion par la Culture <a class="header-anchor" href="#_3-1-canal-de-promotion-par-la-culture" aria-label="Permalink to &quot;3.1 Canal de Promotion par la Culture&quot;">​</a></h3><p>La promotion par la culture est le canal de mobilité des classes le plus important. Par l&#39;ouverture des Trois Cents Systèmes de Culture Originels, la civilisation symbiotique offre à chaque individu un chemin de promotion par la culture clair :</p><ul><li><strong>Promotion de stade</strong> : les cultivateurs élèvent leur stade par la culture, du primaire à l&#39;intermédiaire, à l&#39;avancé et au suprême ; chaque percée de stade peut entraîner une ascension de classe</li><li><strong>Percée de système</strong> : les cultivateurs qui obtiennent des résultats de percée dans un certain système de culture peuvent obtenir une augmentation du Degré de Symbiose et une ascension de classe</li><li><strong>Innovation technologique</strong> : les cultivateurs qui obtiennent des résultats innovants dans la technologie de culture, la technologie d&#39;ingénierie et d&#39;autres domaines peuvent recevoir des honneurs et des récompenses en ressources, favorisant l&#39;ascension de classe</li></ul><p>Le principe fondamental du canal de promotion par la culture est « un chemin pour chacun » — quelle que soit la naissance, pourvu que l&#39;on cultive assidûment, il existe une opportunité d&#39;ascension de classe.</p><h3 id="_3-2-canal-de-promotion-par-la-contribution" tabindex="-1">3.2 Canal de Promotion par la Contribution <a class="header-anchor" href="#_3-2-canal-de-promotion-par-la-contribution" aria-label="Permalink to &quot;3.2 Canal de Promotion par la Contribution&quot;">​</a></h3><p>Outre le stade de culture, les contributions à la civilisation symbiotique sont également une base importante de la mobilité des classes :</p><ul><li><strong>Contributions au service public</strong> : participer à des services publics tels que l&#39;entretien de l&#39;ancre, l&#39;orientation par les mentors et les secours d&#39;urgence, accumuler des points de contribution</li><li><strong>Contributions à la recherche technologique</strong> : apporter des contributions de recherche dans des domaines tels que la technologie de culture et la technologie d&#39;ingénierie</li><li><strong>Contributions à la diffusion culturelle</strong> : diffuser les concepts symbiotiques, créer des œuvres culturelles et promouvoir les échanges entre civilisations</li><li><strong>Contributions à la participation à la gouvernance</strong> : participer à la gouvernance sociale, proposer des recommandations politiques et favoriser l&#39;optimisation institutionnelle</li></ul><p>Le principe fondamental du canal de promotion par la contribution est « plus de travail, plus de récompense » — plus la contribution à la civilisation symbiotique est grande, plus les retours et les promotions de classe sont importants.</p><h3 id="_3-3-canal-de-promotion-par-l-education" tabindex="-1">3.3 Canal de Promotion par l&#39;Éducation <a class="header-anchor" href="#_3-3-canal-de-promotion-par-l-education" aria-label="Permalink to &quot;3.3 Canal de Promotion par l&#39;Éducation&quot;">​</a></h3><p>L&#39;éducation est une échelle importante pour la mobilité des classes. La civilisation symbiotique a établi un système complet de promotion par l&#39;éducation :</p><ul><li><strong>Éducation de base</strong> : offrir à chaque individu une éducation de culture de base gratuite, garantissant l&#39;équité des points de départ</li><li><strong>Éducation avancée</strong> : sélectionner par évaluation les excellents élèves pour les académies de culture avancée, leur offrant une formation de niveau supérieur</li><li><strong>Éducation d&#39;élite</strong> : sélectionner les individus les plus prometteurs pour les programmes de formation d&#39;élite, leur offrant un soutien de ressources de premier ordre</li><li><strong>Éducation permanente</strong> : offrir aux individus de tous âges des opportunités d&#39;apprentissage et d&#39;amélioration continues</li></ul><p>Le principe fondamental du canal de promotion par l&#39;éducation est « l&#39;égalité des chances » — chaque individu a une opportunité égale de réaliser une ascension de classe par l&#39;éducation.</p><h3 id="_3-4-canal-de-promotion-special" tabindex="-1">3.4 Canal de Promotion Spécial <a class="header-anchor" href="#_3-4-canal-de-promotion-special" aria-label="Permalink to &quot;3.4 Canal de Promotion Spécial&quot;">​</a></h3><p>Pour les individus qui apportent des contributions exceptionnelles ou manifestent des talents spéciaux dans des domaines particuliers, la civilisation symbiotique a établi des canaux de promotion spéciaux :</p><ul><li><strong>Promotion exceptionnelle des talents spéciaux</strong> : les individus ayant des talents spéciaux ou des contributions spéciales dans un domaine peuvent être promus hors normes</li><li><strong>Promotion méritoire en cas d&#39;urgence</strong> : les individus qui se distinguent en répondant à des urgences (catastrophes, invasions, crises, etc.) peuvent recevoir une promotion rapide</li><li><strong>Promotion pour contributions à l&#39;exploration interplans</strong> : les individus qui apportent des contributions exceptionnelles à l&#39;exploration et à l&#39;archéologie interplans peuvent recevoir une promotion</li></ul><h2 id="iv-garanties-institutionnelles-contre-le-figement-des-classes" tabindex="-1">IV. Garanties Institutionnelles Contre le Figement des Classes <a class="header-anchor" href="#iv-garanties-institutionnelles-contre-le-figement-des-classes" aria-label="Permalink to &quot;IV. Garanties Institutionnelles Contre le Figement des Classes&quot;">​</a></h2><p>La fluidité de la mobilité des classes exige des garanties institutionnelles. La civilisation symbiotique a établi les institutions suivantes pour prévenir le figement des classes :</p><h3 id="_4-1-institution-antimonopole" tabindex="-1">4.1 Institution Antimonopole <a class="header-anchor" href="#_4-1-institution-antimonopole" aria-label="Permalink to &quot;4.1 Institution Antimonopole&quot;">​</a></h3><p>La Constitution Symbiotique et la Loi Antimonopole interdisent explicitement à toute organisation ou individu de monopoliser les ressources de culture, les systèmes de culture, les opportunités éducatives, etc. L&#39;institution antimonopole empêche les groupes d&#39;intérêts établis de consolider leurs privilèges en monopolisant les ressources, garantissant l&#39;ouverture et la fluidité des ressources.</p><h3 id="_4-2-institution-des-impots-sur-l-heritage-et-sur-les-donations" tabindex="-1">4.2 Institution des Impôts sur l&#39;Héritage et sur les Donations <a class="header-anchor" href="#_4-2-institution-des-impots-sur-l-heritage-et-sur-les-donations" aria-label="Permalink to &quot;4.2 Institution des Impôts sur l&#39;Héritage et sur les Donations&quot;">​</a></h3><p>Afin d&#39;empêcher la richesse et les ressources de provoquer un figement des classes par transmission intergénérationnelle, la civilisation symbiotique met en œuvre un système progressif d&#39;impôts sur l&#39;héritage et sur les donations. Les héritages et donations de grande valeur doivent payer une part d&#39;impôt relativement élevée, reversée dans le pool de ressources publiques pour le bénéfice commun de tous les êtres symbiotiques.</p><h3 id="_4-3-institution-de-l-equite-educative" tabindex="-1">4.3 Institution de l&#39;Équité Éducative <a class="header-anchor" href="#_4-3-institution-de-l-equite-educative" aria-label="Permalink to &quot;4.3 Institution de l&#39;Équité Éducative&quot;">​</a></h3><p>La civilisation symbiotique garantit l&#39;équité éducative par la Loi sur la Garantie de l&#39;Éducation :</p><ul><li>L&#39;éducation de base est gratuite et ouverte à tous les citoyens</li><li>La sélection pour l&#39;éducation avancée et l&#39;éducation d&#39;élite repose sur la capacité et le potentiel comme critères, non sur la naissance et la richesse</li><li>Un soutien et une compensation éducatifs supplémentaires sont fournis aux groupes défavorisés</li><li>Toute forme de discrimination éducative et de privilège éducatif est interdite</li></ul><h3 id="_4-4-institution-de-surveillance-de-la-mobilite-des-classes" tabindex="-1">4.4 Institution de Surveillance de la Mobilité des Classes <a class="header-anchor" href="#_4-4-institution-de-surveillance-de-la-mobilite-des-classes" aria-label="Permalink to &quot;4.4 Institution de Surveillance de la Mobilité des Classes&quot;">​</a></h3><p>Le réseau symbiotique surveille en temps réel la mobilité des classes sociales, avec des indicateurs de surveillance fondamentaux comprenant :</p><ul><li><strong>Taux de mobilité intergénérationnelle</strong> : le degré de différence entre la classe de la génération enfant et celle de la génération parent</li><li><strong>Taux de mobilité ascendante</strong> : la proportion d&#39;individus réalisant une ascension de classe à chaque cycle</li><li><strong>Taux de mobilité descendante</strong> : la proportion d&#39;individus subissant une descente de classe à chaque cycle</li><li><strong>Indice de figement des classes</strong> : le degré d&#39;« hérédité » au sein de chaque classe</li></ul><p>Lorsque les indicateurs de surveillance montrent que la mobilité des classes est entravée ou qu&#39;une tendance au figement apparaît, les institutions de gouvernance procèdent rapidement à des ajustements politiques pour garantir la fluidité de la mobilité des classes.</p><h2 id="v-differences-de-structure-sociale-entre-les-cinq-typologies-de-civilisation" tabindex="-1">V. Différences de Structure Sociale Entre les Cinq Typologies de Civilisation <a class="header-anchor" href="#v-differences-de-structure-sociale-entre-les-cinq-typologies-de-civilisation" aria-label="Permalink to &quot;V. Différences de Structure Sociale Entre les Cinq Typologies de Civilisation&quot;">​</a></h2><p>Les cinq typologies de civilisation symbiotique ont chacune leurs caractéristiques en matière de structure sociale :</p><table tabindex="0"><thead><tr><th>Typologie</th><th>Caractéristiques de la structure sociale</th><th>Caractéristiques de la mobilité des classes</th></tr></thead><tbody><tr><td>Type Intensif d&#39;Asie Orientale</td><td>Orientation collective, hiérarchie claire, basé sur les familles et les sectes</td><td>Canaux de mobilité principalement par promotion dans les sectes, vitesse moyenne</td></tr><tr><td>Type de Bien-être Nordique</td><td>Aplatissement, grande égalité, classes faibles</td><td>Écarts de classes faibles, pression de mobilité faible, vitesse plus lente</td></tr><tr><td>Type Pluraliste Nord-Américain</td><td>Orientation marché, pluralisme, concurrence intense</td><td>Canaux de mobilité principalement par concurrence de marché, mobilité rapide mais grands écarts</td></tr><tr><td>Type Social Européen Continental</td><td>Corporatisme, cogestion patronat-salariat, démocratie délibérative</td><td>Canaux de mobilité principalement par qualifications professionnelles et négociation collective, mobilité stable</td></tr><tr><td>Type de Rattrapage en Développement</td><td>Gouvernement fort, mobilité rapide, développement par paliers</td><td>Vitesse de mobilité rapide, nombreuses opportunités d&#39;ascension, vitalité sociale abondante</td></tr></tbody></table><p>Bien que les structures sociales des différentes typologies diffèrent, elles suivent toutes les principes fondamentaux de la Constitution Symbiotique et s&#39;engagent toutes à construire une structure sociale ouverte, fluide, équitable et dynamique.</p><h2 id="conclusion" tabindex="-1">Conclusion <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusion&quot;">​</a></h2><p>La structure sociale et la mobilité des classes sont l&#39;un des sujets fondamentaux de la construction institutionnelle de la Civilisation Symbiotique de l&#39;Ancre. Par la division dynamique des classes centrée sur le Degré de Symbiose et le Stade de Culture, les mécanismes de mobilité des classes à canaux multiples et les garanties institutionnelles contre le figement des classes, la civilisation symbiotique a construit une structure sociale ouverte, fluide, équitable et dynamique. Dans une telle structure sociale, chaque individu peut changer son destin par ses propres efforts, les ressources sociales peuvent affluer vers les personnes les plus compétentes et les plus contributrices, et toute la civilisation maintient une vitalité de développement abondante. C&#39;est précisément la base sociale importante permettant à la civilisation symbiotique de réaliser la progression commune de toutes les races.</p><h2 id="documents-connexes" tabindex="-1">Documents Connexes <a class="header-anchor" href="#documents-connexes" aria-label="Permalink to &quot;Documents Connexes&quot;">​</a></h2><ul><li>26-个体与集体平衡原理 (Principes de l&#39;Équilibre Individu-Collectif)</li><li>29-共生度评估体系 (Système d&#39;Évaluation du Degré de Symbiose)</li><li>30-五种共生文明分型总览 (Aperçu des Cinq Typologies de Civilisation Symbiotique)</li></ul>',51)])])}const b=i(n,[["render",o]]);export{m as __pageData,b as default};
